def transform(grid):
    H, W = len(grid), len(grid[0])
    ones = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    a = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    h, w = len(a), len(a[0])

    transforms = [
        lambda r, c: (r, c),
        lambda r, c: (c, h - 1 - r),
        lambda r, c: (h - 1 - r, w - 1 - c),
        lambda r, c: (w - 1 - c, r),
        lambda r, c: (r, w - 1 - c),
        lambda r, c: (h - 1 - r, c),
        lambda r, c: (c, r),
        lambda r, c: (w - 1 - c, h - 1 - r),
    ]

    # Dots outside the board identify the orientation of the marked board.
    outside = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v not in (0, 1) and not (r0 <= r <= r1 and c0 <= c <= c1):
                outside.setdefault(v, (r, c))

    anchors = {}
    for color in outside:
        spots = [(r, c) for r in range(h) for c in range(w) if a[r][c] == color]
        if len(spots) == 1:
            anchors[color] = spots[0]

    if len(anchors) < 2:
        fn = transforms[0]
    else:
        def normalize(points):
            rs = [p[0] for p in points]
            cs = [p[1] for p in points]
            rmin, rmax, cmin, cmax = min(rs), max(rs), min(cs), max(cs)
            return [
                ((r - rmin) / max(1, rmax - rmin),
                 (c - cmin) / max(1, cmax - cmin))
                for r, c in points
            ]

        ext_points = [outside[k] for k in anchors]
        ext_norm = normalize(ext_points)
        best_score, fn = float("inf"), transforms[0]

        for f in transforms:
            coords = [f(*anchors[k]) for k in anchors]
            norm = normalize(coords)
            score = sum((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
                        for p, q in zip(norm, ext_norm))
            if score < best_score:
                best_score, fn = score, f

    out_h = max(fn(r, c)[0] for r in range(h) for c in range(w)) + 1
    out_w = max(fn(r, c)[1] for r in range(h) for c in range(w)) + 1
    out = [[1] * out_w for _ in range(out_h)]
    for r in range(h):
        for c in range(w):
            rr, cc = fn(r, c)
            out[rr][cc] = a[r][c]
    return out
